   ("resolution", {| rule_binders := [(0, (PSymbol "Bool")); (1, (PSymbol "Bool")); (2, (PSymbol "Bool")); (3, (PSymbol "Bool"))]; rule_arguments := [(PVar 2); (PVar 3)]; rule_premises := [(PVar 0); (PVar 1)]; rule_assumption := None; rule_premise_list := None; rule_requires := []; rule_conclusion := (ECall "$from_clause" [(ENative "eo::list_concat" [(ESymbol "or"); (EIf (EEq (EIf (EVar 2) (EVar 3) (EApply (ESymbol "not") (EVar 3))) (ECall "$to_clause" [(EVar 0)])) (ESymbol "false") (ENative "eo::list_erase" [(ESymbol "or"); (ECall "$to_clause" [(EVar 0)]); (EIf (EVar 2) (EVar 3) (EApply (ESymbol "not") (EVar 3)))])); (EIf (EEq (EIf (EVar 2) (EApply (ESymbol "not") (EVar 3)) (EVar 3)) (ECall "$to_clause" [(EVar 1)])) (ESymbol "false") (ENative "eo::list_erase" [(ESymbol "or"); (ECall "$to_clause" [(EVar 1)]); (EIf (EVar 2) (EApply (ESymbol "not") (EVar 3)) (EVar 3))]))])]) |});
   ("scope", {| rule_binders := [(0, (PSymbol "Bool")); (1, (PSymbol "Bool"))]; rule_arguments := []; rule_premises := [(PVar 1)]; rule_assumption := (Some (PVar 0)); rule_premise_list := None; rule_requires := []; rule_conclusion := (EApply (EApply (ESymbol "=>") (EVar 0)) (EVar 1)) |});
   ("symm", {| rule_binders := [(0, (PSymbol "Bool"))]; rule_arguments := []; rule_premises := [(PVar 0)]; rule_assumption := None; rule_premise_list := None; rule_requires := []; rule_conclusion := (ECall "$mk_symm" [(EVar 0)]) |});
   ("trans", {| rule_binders := [(0, (PSymbol "Type")); (1, (PVar 0)); (2, (PVar 0)); (3, (PSymbol "Bool"))]; rule_arguments := []; rule_premises := [(PApply (PApply (PSymbol "and") (PApply (PApply (PSymbol "=") (PVar 1)) (PVar 2))) (PVar 3))]; rule_assumption := None; rule_premise_list := (Some "and"); rule_requires := []; rule_conclusion := (ECall "$mk_trans" [(EVar 1); (EVar 2); (EVar 3)]) |});
