   ("true_intro", {| rule_binders := [(0, (PSymbol "Bool"))]; rule_arguments := []; rule_premises := [(PVar 0)]; rule_assumption := None; rule_premise_list := None; rule_requires := []; rule_conclusion := (EApply (EApply (ESymbol "=") (EVar 0)) (ESymbol "true")) |})].

Definition derive_context_with (extra : primitive_hook) (fuel : nat) (typeof : term -> option term)
    (name : string) (assumption : option term) (args premises : list term) : option term :=
  let canon := rename_symbols cpc_aliases in
  let surface := rename_symbols cpc_surface_names in
  let all_inputs := ((match assumption with Some a => [a] | None => [] end) ++ args ++ premises)%list in
  if forallb (surface_supported cpc_blocked_operators cpc_binary_operators) (map canon all_inputs) then
  option_map surface (run_surface_rule_assuming_with extra fuel
    (fun t => option_map canon (typeof (surface t)))
    cpc_operators cpc_programs cpc_rules name (option_map canon assumption) (map canon args) (map canon premises)) else None.

Definition derive_with (extra : primitive_hook) (fuel : nat) (typeof : term -> option term)
    (name : string) (args premises : list term) : option term :=
  derive_context_with extra fuel typeof name None args premises.
Definition derive_assuming_with (extra : primitive_hook) (fuel : nat) (typeof : term -> option term)
    (name : string) (assumption : term) (args premises : list term) : option term :=
  derive_context_with extra fuel typeof name (Some assumption) args premises.

Definition derive := derive_with no_extension.
Definition derive_assuming := derive_assuming_with no_extension.
